create table if not exists public.media_items(id bigint generated by default as identity primary key,path text not null unique,filename text not null,mime_type text not null,size bigint,owner_id uuid not null references auth.users(id) on delete cascade,created_at timestamptz not null default now());alter table public.media_items enable row level security;drop policy if exists "family can read media metadata" on public.media_items;create policy "family can read media metadata" on public.media_items for select to authenticated using (true);drop policy if exists "family can add media metadata" on public.media_items;create policy "family can add media metadata" on public.media_items for insert to authenticated with check (true);drop policy if exists "family can delete media metadata" on public.media_items;create policy "family can delete media metadata" on public.media_items for delete to authenticated using (true);drop policy if exists "family can upload" on storage.objects;create policy "family can upload" on storage.objects for insert to authenticated with check (bucket_id='family-media');drop policy if exists "family can read" on storage.objects;create policy "family can read" on storage.objects for select to authenticated using (bucket_id='family-media');drop policy if exists "family can delete" on storage.objects;create policy "family can delete" on storage.objects for delete to authenticated using (bucket_id='family-media');